struct OutputTimingStats {
  double local{0.0};
  double min{0.0};
  double mean{0.0};
  double max{0.0};
};

struct ProcessMemorySnapshot {
  long vm_kb{-1};
  long rss_kb{-1};
};

ProcessMemorySnapshot readProcessMemorySnapshot()
{
  ProcessMemorySnapshot snapshot;
  std::ifstream status("/proc/self/status");
  std::string line;
  while (std::getline(status, line)) {
    std::istringstream fields(line);
    std::string key;
    long value = -1;
    std::string unit;
    if (!(fields >> key >> value >> unit)) {
      continue;
    }
    if (key == "VmSize:") {
      snapshot.vm_kb = value;
    } else if (key == "VmRSS:") {
      snapshot.rss_kb = value;
    }
  }
  return snapshot;
}

OutputTimingStats reduceOutputTiming(double local, const svmp::MeshComm& comm)
{
  OutputTimingStats stats;
  stats.local = local;
  stats.min = local;
  stats.mean = local;
  stats.max = local;

#ifdef MESH_HAS_MPI
  int initialized = 0;
  MPI_Initialized(&initialized);
  if (initialized && comm.size() > 1) {
    double sum = 0.0;
    MPI_Allreduce(&local, &stats.min, 1, MPI_DOUBLE, MPI_MIN, comm.native());
    MPI_Allreduce(&local, &stats.max, 1, MPI_DOUBLE, MPI_MAX, comm.native());
    MPI_Allreduce(&local, &sum, 1, MPI_DOUBLE, MPI_SUM, comm.native());
    stats.mean = sum / static_cast<double>(comm.size());
  }
#else
  (void)comm;
#endif

  return stats;
}

void printOutputTimingLine(const char* label,
                           const OutputTimingStats& stats,
                           bool mpi_parallel,
                           double parent_seconds = 0.0)
{
  const double pct = parent_seconds > 0.0 ? 100.0 * stats.local / parent_seconds : 0.0;
  if (mpi_parallel) {
    std::fprintf(stderr,
                 "  %-24s %10.6f s  (%5.1f%%)  rank min/mean/max %10.6f / %10.6f / %10.6f s\n",
                 label,
                 stats.local,
                 pct,
                 stats.min,
                 stats.mean,
                 stats.max);
  } else {
    std::fprintf(stderr,
                 "  %-24s %10.6f s  (%5.1f%%)\n",
                 label,
                 stats.local,
                 pct);
  }
}

/// @brief Detect the number of physical CPU cores (excluding hyperthreads).
/// Falls back to std::thread::hardware_concurrency() if detection fails.
int detectPhysicalCores()
{
  int physical = 0;
#if defined(__linux__)
  // Count unique physical cores from sysfs topology.
  // Each /sys/devices/system/cpu/cpuN/topology/thread_siblings_list contains
  // the list of sibling logical CPUs sharing one physical core. We count
  // unique "first sibling" entries to get the physical core count.
  std::set<int> seen_first_siblings;
  for (int cpu = 0; cpu < 4096; ++cpu) {
    char path[128];
    std::snprintf(path, sizeof(path),
                  "/sys/devices/system/cpu/cpu%d/topology/thread_siblings_list", cpu);
    std::ifstream f(path);
    if (!f.is_open()) break;
    int first_sibling = -1;
    // thread_siblings_list format: "0-1" or "0,1" or "0" — first integer is
    // the lowest-numbered sibling.
    f >> first_sibling;
    if (first_sibling >= 0) {
      seen_first_siblings.insert(first_sibling);
    }
  }
  physical = static_cast<int>(seen_first_siblings.size());
#endif
  if (physical <= 0) {
    physical = static_cast<int>(std::max(1u, std::thread::hardware_concurrency()));
  }
  return physical;
}

/// @brief Automatically configure OpenMP thread count based on physical cores
/// and number of MPI ranks sharing this node. If OMP_NUM_THREADS is already set
/// by the user, that value is respected.
///
/// Uses physical cores (not logical/hyperthreaded) because FEM workloads are
/// memory-bandwidth-bound and hyperthreading typically hurts performance.
///
/// Logic: threads_per_rank = floor(physical_cores / ranks_on_this_node)
///        clamped to [1, physical_cores].
void configureOpenMPThreads(const svmp::MeshComm& comm)
{
#ifdef _OPENMP
  // If user explicitly set OMP_NUM_THREADS, respect it.
  if (std::getenv("OMP_NUM_THREADS")) {
    return;
  }

  const int physical_cores = detectPhysicalCores();

  // Determine how many MPI ranks share this physical node.
  int ranks_on_node = 1;
#ifdef MESH_HAS_MPI
  int mpi_initialized = 0;
  MPI_Initialized(&mpi_initialized);
  if (mpi_initialized) {
    MPI_Comm node_comm = MPI_COMM_NULL;
    MPI_Comm_split_type(comm.native(), MPI_COMM_TYPE_SHARED, comm.rank(),
                        MPI_INFO_NULL, &node_comm);
    if (node_comm != MPI_COMM_NULL) {
      MPI_Comm_size(node_comm, &ranks_on_node);
      MPI_Comm_free(&node_comm);
    }
  }
#else
  (void)comm;
#endif

  if (ranks_on_node < 1) ranks_on_node = 1;
  int threads = std::max(1, physical_cores / ranks_on_node);
  omp_set_num_threads(threads);
#else
  (void)comm;
#endif
}

std::string trim_copy(std::string s)
{
  auto not_space = [](unsigned char ch) { return !std::isspace(ch); };
  s.erase(s.begin(), std::find_if(s.begin(), s.end(), not_space));
  s.erase(std::find_if(s.rbegin(), s.rend(), not_space).base(), s.end());
  return s;
}

bool parseBoolEnv(const char* name, bool default_value)
{
  const char* env = std::getenv(name);
  if (!env) {
    return default_value;
  }
  std::string v(env);
  std::transform(v.begin(), v.end(), v.begin(),
                 [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
  if (v == "1" || v == "true" || v == "on" || v == "yes") {
    return true;
  }
  if (v == "0" || v == "false" || v == "off" || v == "no") {
    return false;
  }
  return default_value;
}

bool generalizedAlphaPdeRateInitializationRequested(
    bool active_cut_domain_present)
{
  // Active-cut systems used to default this solve off because their dt-only
  // operator contains exact zero rows outside the retained physical domain.
  // TimeLoop now regularizes precisely those rows, so an active cut is not a
  // reason to replace the PDE-consistent initial rate with zero.  Keep the
  // argument explicit so this policy remains covered at the application
  // boundary if active-cut startup handling changes again.
  (void)active_cut_domain_present;
  return parseBoolEnv("SVMP_GENERALIZED_ALPHA_PDE_UDOT_INIT", true);
}

struct TransientTimeIntegrationSelection {
  svmp::FE::timestepping::SchemeKind scheme{
      svmp::FE::timestepping::SchemeKind::GeneralizedAlpha};
  std::string_view canonical_name{"GeneralizedAlpha"};
  std::optional<double> generalized_alpha_rho_inf{0.5};
  svmp::FE::Real stage_alpha_f{svmp::FE::Real{1.0}};
};

constexpr std::array<std::pair<
    std::string_view,
    svmp::FE::timestepping::SchemeKind>, 2>
    kTransientTimeIntegrationSchemes{{
        {"GeneralizedAlpha",
         svmp::FE::timestepping::SchemeKind::GeneralizedAlpha},
        {"BackwardEuler",
         svmp::FE::timestepping::SchemeKind::BackwardEuler},
    }};

svmp::FE::timestepping::SchemeKind parseTransientTimeIntegrationScheme(
    std::string_view name)
{
  const auto entry = std::find_if(
      kTransientTimeIntegrationSchemes.begin(),
      kTransientTimeIntegrationSchemes.end(),
      [name](const auto& candidate) {
        return candidate.first == name;
      });
  if (entry == kTransientTimeIntegrationSchemes.end()) {
    throw std::runtime_error(
        "[svMultiPhysics::Application] Unsupported "
        "<Transient_time_integration_scheme> '" +
        std::string(name) +
        "'. Supported values are exactly 'GeneralizedAlpha' and "
        "'BackwardEuler'.");
  }
  return entry->second;
}

std::string_view transientTimeIntegrationSchemeName(
    svmp::FE::timestepping::SchemeKind scheme)
{
  const auto entry = std::find_if(
      kTransientTimeIntegrationSchemes.begin(),
      kTransientTimeIntegrationSchemes.end(),
      [scheme](const auto& candidate) {
        return candidate.second == scheme;
      });
  if (entry == kTransientTimeIntegrationSchemes.end()) {
    throw std::logic_error(
        "[svMultiPhysics::Application] Transient scheme is outside the "
        "application-supported set.");
  }
  return entry->first;
}

TransientTimeIntegrationSelection resolveTransientTimeIntegrationSelection(
    const GeneralSimulationParameters& parameters)
{
  const auto scheme =
      parseTransientTimeIntegrationScheme(
          parameters.transient_time_integration_scheme.value());
  TransientTimeIntegrationSelection selection;
  selection.scheme = scheme;
  selection.canonical_name = transientTimeIntegrationSchemeName(scheme);
  if (scheme == svmp::FE::timestepping::SchemeKind::BackwardEuler) {
    // A spectral radius is deliberately inapplicable to backward Euler,
    // which uses the accepted endpoint.
    selection.generalized_alpha_rho_inf = std::nullopt;
    selection.stage_alpha_f = svmp::FE::Real{1.0};
    return selection;
  }

  const double rho_inf =
      parameters.spectral_radius_of_infinite_time_step.value();
  const auto generalized_alpha =
      svmp::FE::timestepping::utils::generalizedAlphaFirstOrderFromRhoInf(
          rho_inf);
  selection.generalized_alpha_rho_inf = rho_inf;
  selection.stage_alpha_f =
      static_cast<svmp::FE::Real>(generalized_alpha.alpha_f);
  return selection;
}

double parseDoubleEnv(const char* name, double default_value)
{
  const char* env = std::getenv(name);
  if (!env) {
    return default_value;
  }
  char* end = nullptr;
  const double value = std::strtod(env, &end);
  if (end == env || !std::isfinite(value)) {
    return default_value;
  }
  return value;
}

int parseIntEnv(const char* name, int default_value)
{
  const char* env = std::getenv(name);
  if (!env) {
    return default_value;
  }
  char* end = nullptr;
  const long value = std::strtol(env, &end, 10);
  if (end == env || value < static_cast<long>(std::numeric_limits<int>::min()) ||
      value > static_cast<long>(std::numeric_limits<int>::max())) {
    return default_value;
  }
  return static_cast<int>(value);
}

void applyGeneratedStateOuterRelaxationEnvOptions(
    svmp::FE::timestepping::NewtonOptions& opts)
{
  auto& relaxation =
      opts.external_state_fixed_point.dynamic_relaxation;
  relaxation.enabled = parseBoolEnv(
      "SVMP_GENERATED_STATE_OUTER_DYNAMIC_RELAXATION",
      relaxation.enabled);
  relaxation.initial_factor = parseDoubleEnv(
      "SVMP_GENERATED_STATE_OUTER_DYNAMIC_RELAXATION_INITIAL_FACTOR",
      relaxation.initial_factor);
  relaxation.minimum_factor = parseDoubleEnv(
      "SVMP_GENERATED_STATE_OUTER_DYNAMIC_RELAXATION_MINIMUM_FACTOR",
      relaxation.minimum_factor);
  relaxation.maximum_factor = parseDoubleEnv(
      "SVMP_GENERATED_STATE_OUTER_DYNAMIC_RELAXATION_MAXIMUM_FACTOR",
      relaxation.maximum_factor);
  relaxation.denominator_relative_tolerance = parseDoubleEnv(
      "SVMP_GENERATED_STATE_OUTER_DYNAMIC_RELAXATION_DENOMINATOR_RELATIVE_TOLERANCE",
      relaxation.denominator_relative_tolerance);
}

void applyNewtonLineSearchEnvOptions(svmp::FE::timestepping::NewtonOptions& opts)
{
  opts.line_search_max_iterations =
      std::max(1, parseIntEnv("SVMP_NEWTON_LINE_SEARCH_MAX_ITERATIONS",
                              opts.line_search_max_iterations));
  opts.line_search_alpha_min =
      parseDoubleEnv("SVMP_NEWTON_LINE_SEARCH_ALPHA_MIN",
                     opts.line_search_alpha_min);
  opts.line_search_shrink =
      parseDoubleEnv("SVMP_NEWTON_LINE_SEARCH_SHRINK",
                     opts.line_search_shrink);
  opts.line_search_c1 =
      parseDoubleEnv("SVMP_NEWTON_LINE_SEARCH_C1",
                     opts.line_search_c1);
  opts.line_search_fail_on_no_reduction =
      parseBoolEnv("SVMP_NEWTON_LINE_SEARCH_FAIL_ON_NO_REDUCTION",
                   opts.line_search_fail_on_no_reduction);
}

void applyNewtonToleranceEnvOptions(svmp::FE::timestepping::NewtonOptions& opts)
{
  if (std::getenv("SVMP_NEWTON_ABS_TOLERANCE")) {
    const double value =
        parseDoubleEnv("SVMP_NEWTON_ABS_TOLERANCE", opts.abs_tolerance);
    if (value >= 0.0) {
      opts.abs_tolerance = value;
    }
  }
  if (std::getenv("SVMP_NEWTON_REL_TOLERANCE")) {
    const double value =
        parseDoubleEnv("SVMP_NEWTON_REL_TOLERANCE", opts.rel_tolerance);
    if (value >= 0.0) {
      opts.rel_tolerance = value;
    }
  }
}

void applyNewtonLineSearchXmlOptions(
    const GeneralSimulationParameters& general_params,
    svmp::FE::timestepping::NewtonOptions& opts)
{
  if (general_params.newton_line_search_max_iterations.defined()) {
    opts.line_search_max_iterations =
        std::max(1, general_params.newton_line_search_max_iterations.value());
  }
  if (general_params.newton_line_search_fail_on_no_reduction.defined()) {
    opts.line_search_fail_on_no_reduction =
        general_params.newton_line_search_fail_on_no_reduction.value();
  }
}

void applyNewtonPseudoTransientEnvOptions(svmp::FE::timestepping::NewtonOptions& opts)
{
  auto& ptc = opts.pseudo_transient;
  ptc.enabled =
      parseBoolEnv("SVMP_NEWTON_PTC", ptc.enabled);
  ptc.activate_on_linear_failure =
      parseBoolEnv("SVMP_NEWTON_PTC_ACTIVATE_ON_LINEAR_FAILURE",
                   ptc.activate_on_linear_failure);
  ptc.gamma_initial =
      std::max(0.0,
               parseDoubleEnv("SVMP_NEWTON_PTC_GAMMA_INITIAL",
                              ptc.gamma_initial));

  const double gamma_growth =
      parseDoubleEnv("SVMP_NEWTON_PTC_GAMMA_GROWTH", ptc.gamma_growth);
  if (gamma_growth > 1.0) {
    ptc.gamma_growth = gamma_growth;
  }

  ptc.gamma_max =
      std::max(0.0,
               parseDoubleEnv("SVMP_NEWTON_PTC_GAMMA_MAX",
                              ptc.gamma_max));
  ptc.gamma_drop_tolerance =
      std::max(0.0,
               parseDoubleEnv("SVMP_NEWTON_PTC_GAMMA_DROP_TOLERANCE",
                              ptc.gamma_drop_tolerance));
  ptc.max_linear_retries =
      std::max(1,
               parseIntEnv("SVMP_NEWTON_PTC_MAX_LINEAR_RETRIES",
                           ptc.max_linear_retries));
  ptc.update_from_residual_ratio =
      parseBoolEnv("SVMP_NEWTON_PTC_UPDATE_FROM_RESIDUAL_RATIO",
                   ptc.update_from_residual_ratio);
}

std::string lower_copy(std::string s)
{
  std::transform(s.begin(), s.end(), s.begin(),
                 [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
  return s;
}

bool oopStateTraceEnabled()
{
  const char* env = std::getenv("SVMP_OOP_SOLVER_TRACE");
  if (env == nullptr) {
    return false;
  }
  const auto v = lower_copy(env);
  return !(v == "0" || v == "false" || v == "off" || v == "no");
}

void traceStateVectorFields(const svmp::FE::systems::FESystem& system,
                            svmp::FE::backends::GenericVector& vector,
                            const char* label)
{
  if (!oopStateTraceEnabled()) {
    return;
  }
  const auto view = vector.createAssemblyView();
  if (!view) {
    return;
  }
  const auto& fields = system.fieldMap();
  std::ostringstream oss;
  oss << "[svMultiPhysics::Application] state_vector diagnostic=state_vector_fields"
      << " label='" << label << "'";
  for (std::size_t field = 0; field < fields.numFields(); ++field) {
    const auto& rec = fields.getField(field);
    const auto range = fields.getFieldDofRange(field);
    double sq_norm = 0.0;
    double sum = 0.0;
    double min_value = std::numeric_limits<double>::infinity();
    double max_value = -std::numeric_limits<double>::infinity();
    std::uint64_t count = 0;
    for (svmp::FE::GlobalIndex dof = range.first; dof < range.second; ++dof) {
      const double value = static_cast<double>(view->getVectorEntry(dof));
      sq_norm += value * value;
      sum += value;
      min_value = std::min(min_value, value);
      max_value = std::max(max_value, value);
      ++count;
    }
    const double mean = count > 0 ? sum / static_cast<double>(count) : 0.0;
    oss << " [" << rec.name
        << " dofs=" << count
        << " norm=" << std::sqrt(std::max(0.0, sq_norm))
        << " mean=" << mean
        << " min=" << (count > 0 ? min_value : 0.0)
        << " max=" << (count > 0 ? max_value : 0.0)
        << "]";
  }
  application::core::oopCout() << oss.str() << std::endl;
}

bool parse_bool_relaxed(const std::string& raw)
{
  const auto v = lower_copy(trim_copy(raw));
  if (v == "true" || v == "1" || v == "yes" || v == "on") {
    return true;
  }
  if (v == "false" || v == "0" || v == "no" || v == "off") {
    return false;
  }
  return false;
}

std::string normalized_token(std::string value)
{
  value = lower_copy(trim_copy(std::move(value)));
  value.erase(std::remove_if(value.begin(), value.end(),
                             [](unsigned char c) {
                               return c == '_' || c == '-' || std::isspace(c);
                             }),
              value.end());
  return value;
}

std::optional<std::string> first_defined_parameter(
    const std::map<std::string, std::string>& params,
    std::initializer_list<const char*> keys)
{
  for (const char* key : keys) {
    const auto it = params.find(key);
    if (it != params.end() && !trim_copy(it->second).empty()) {
      return it->second;
    }
  }
  return std::nullopt;
}

std::optional<double> first_defined_double_parameter(
    const std::map<std::string, std::string>& params,
    std::initializer_list<const char*> keys)
{
  if (const auto value = first_defined_parameter(params, keys)) {
    return std::stod(*value);
  }
  return std::nullopt;
}

std::optional<int> first_defined_int_parameter(
    const std::map<std::string, std::string>& params,
    std::initializer_list<const char*> keys)
{
  if (const auto value = first_defined_parameter(params, keys)) {
    return std::stoi(*value);
  }
  return std::nullopt;
}

std::optional<bool> first_defined_bool_parameter(
    const std::map<std::string, std::string>& params,
    std::initializer_list<const char*> keys)
{
  if (const auto value = first_defined_parameter(params, keys)) {
    return parse_bool_relaxed(*value);
  }
  return std::nullopt;
}

svmp::FE::level_set::LevelSetReinitializationMethod
parseLevelSetReinitializationMethod(const std::string& raw)
{
  const auto value = normalized_token(raw);
  using Method = svmp::FE::level_set::LevelSetReinitializationMethod;
  if (value == "projection" || value == "signeddistanceprojection" ||
      value == "repairprojection") {
    return Method::Projection;
  }
  if (value == "hamiltonjacobi" || value == "hamiltonjacobipde" ||
      value == "pde") {
    throw std::runtime_error(
        "[svMultiPhysics::Application] Reinitialization_method=HamiltonJacobiPDE "
        "is reserved until runtime Hamilton-Jacobi reinitialization is implemented; "
        "use 'Projection'.");
  }
  if (value == "fastmarching" || value == "fastmarchingmethod" ||
      value == "fmm") {
    throw std::runtime_error(
        "[svMultiPhysics::Application] Reinitialization_method=FastMarching "
        "is reserved until runtime fast-marching reinitialization is implemented; "
        "use 'Projection'.");
  }
  throw std::runtime_error(
      "[svMultiPhysics::Application] Reinitialization_method currently supports "
      "'Projection' only.");
}

svmp::FE::level_set::LevelSetTransportForm
parseLevelSetTransportForm(const std::string& raw)
{
  const auto value = normalized_token(raw);
  using Form = svmp::FE::level_set::LevelSetTransportForm;
  if (value == "advective" || value == "classical" || value == "standard") {
    return Form::Advective;
  }
  if (value == "conservative" || value == "conservativedivergence" ||
      value == "divergence" || value == "divergenceform") {
    return Form::ConservativeDivergence;
  }
  throw std::runtime_error(
      "[svMultiPhysics::Application] Level-set Transport_form must be one of "
      "'advective' or 'conservative_divergence'.");
}

svmp::FE::level_set::LevelSetVelocitySource
parseLevelSetVelocitySource(const std::string& raw)
{
  const auto value = normalized_token(raw);
  using Source = svmp::FE::level_set::LevelSetVelocitySource;
  if (value.empty() || value == "coupled" || value == "coupledfield" ||
      value == "unknown") {
    return Source::CoupledField;
  }
  if (value == "prescribed" || value == "prescribeddata" ||
      value == "data") {
    return Source::PrescribedData;
  }
  if (value == "constant" || value == "constantvector") {
    return Source::ConstantVector;
  }
  throw std::runtime_error(
      "[svMultiPhysics::Application] Level-set Velocity_source must be one of "
      "'coupled_field', 'prescribed_data', or 'constant_vector'.");
}

svmp::FE::level_set::LevelSetPhaseSide
parseLevelSetPhaseSide(const std::string& raw)
{
  const auto value = normalized_token(raw);
  using Side = svmp::FE::level_set::LevelSetPhaseSide;
  if (value == "negative" || value == "minus") {
    return Side::Negative;
  }
  if (value == "positive" || value == "plus") {
    return Side::Positive;
  }
  throw std::runtime_error(
      "[svMultiPhysics::Application] Conservative_phase_liquid_side must be "
      "'negative' or 'positive'.");
}

std::array<svmp::FE::Real, 3> parseLevelSetVector3(
    const std::string& raw,
    const char* parameter_name)
{
  std::string normalized = raw;
  std::replace(normalized.begin(), normalized.end(), ',', ' ');
  std::istringstream input(normalized);
  std::array<svmp::FE::Real, 3> result{};
  for (auto& value : result) {
    double parsed = 0.0;
    if (!(input >> parsed) || !std::isfinite(parsed)) {
      throw std::runtime_error(
          std::string("[svMultiPhysics::Application] ") + parameter_name +
          " must contain exactly three finite numeric components.");
    }
    value = static_cast<svmp::FE::Real>(parsed);
  }
  std::string trailing;
  if (input >> trailing) {
    throw std::runtime_error(
        std::string("[svMultiPhysics::Application] ") + parameter_name +
        " must contain exactly three finite numeric components.");
  }
  return result;
}

std::string step_reject_reason_to_string(svmp::FE::timestepping::StepRejectReason r)
{
  using svmp::FE::timestepping::StepRejectReason;
  switch (r) {
    case StepRejectReason::NonlinearSolveFailed:
      return "NonlinearSolveFailed";
    case StepRejectReason::ErrorTooLarge:
      return "ErrorTooLarge";
    case StepRejectReason::CutTopologyChanged:
      return "CutTopologyChanged";
  }
  return std::to_string(static_cast<int>(r));
}

const EquationParameters* first_equation(const Parameters& params)
{
  for (const auto* e : params.equation_parameters) {
    if (e) {
      return e;
    }
  }
  return nullptr;
}

const EquationParameters* primary_solver_equation(const Parameters& params)
{
  const auto* first = first_equation(params);
  if (first == nullptr) {
    return nullptr;
  }

  if (first->type.defined() && lower_copy(first->type.value()) == "level_set") {
    for (const auto* e : params.equation_parameters) {
      if (e && e->type.defined() && lower_copy(e->type.value()) == "fluid") {
        return e;
      }
    }
  }

  return first;
}

std::vector<const EquationParameters*>
monolithic_solver_control_equations(const Parameters& params)
{
  std::vector<const EquationParameters*> coupled;
  for (auto* equation : params.equation_parameters) {
    if (equation != nullptr && equation->coupled.defined() &&
        equation->coupled.value()) {
      coupled.push_back(equation);
    }
  }
  if (!coupled.empty()) {
    return coupled;
  }

  if (const auto* primary = primary_solver_equation(params)) {
    return {primary};
  }
  return {};
}

void applyMonolithicEquationNewtonControls(
    const Parameters& params,
    svmp::FE::timestepping::NewtonOptions& options)
{
  const auto equations = monolithic_solver_control_equations(params);
  std::optional<int> maximum_iterations;
  std::optional<int> minimum_iterations;
  std::optional<double> strictest_tolerance;
  std::optional<double> strictest_non_level_set_tolerance;

  for (const auto* equation : equations) {
    if (equation->max_iterations.defined()) {
      maximum_iterations = maximum_iterations.has_value()
          ? std::max(*maximum_iterations, equation->max_iterations.value())
          : equation->max_iterations.value();
    }
    if (equation->min_iterations.defined()) {
      const int value = std::max(0, equation->min_iterations.value());
      minimum_iterations = minimum_iterations.has_value()
          ? std::max(*minimum_iterations, value)
          : value;
    }
    if (equation->tolerance.defined()) {
      const double value = equation->tolerance.value();
      if (value > 0.0) {
        strictest_tolerance = strictest_tolerance.has_value()
            ? std::min(*strictest_tolerance, value)
            : value;
        const auto type = equation->type.defined()
            ? normalized_token(equation->type.value())
            : std::string{};
        if (type != "levelset" && type != "levelsettransport") {
          strictest_non_level_set_tolerance =
              strictest_non_level_set_tolerance.has_value()
              ? std::min(*strictest_non_level_set_tolerance, value)
              : value;
        }
      }
    }
  }

  if (maximum_iterations.has_value()) {
    options.max_iterations = *maximum_iterations;
  }
  if (minimum_iterations.has_value()) {
    options.min_iterations = *minimum_iterations;
  }
  if (strictest_tolerance.has_value()) {
    // Coupled level-set equations receive an owned/global named-field gate
    // below.  Apply the monolithic relative criterion to the remaining
    // equations so a dimensionally smaller transport block cannot force an
    // unrelated momentum/pressure block to its tolerance (or be masked by
    // it).  If the solve contains only level-set equations, retain their
    // strictest tolerance as the monolithic fallback.
    options.rel_tolerance = strictest_non_level_set_tolerance.value_or(
        *strictest_tolerance);
    // Equation <Tolerance> is a relative nonlinear target, not a raw-residual
    // absolute tolerance.  Preserve Newton's configured absolute tolerance;
    // callers may override it explicitly through the Newton options/env path.
  }
}

struct LevelSetMaintenanceRequest {
  struct OpenBoundary {
    std::string face_name{};
    bool inflow{false};
    std::optional<svmp::FE::Real> literal_inflow_value{};
  };

  std::string level_set_field_name{"level_set"};
  double isovalue{0.0};
  svmp::FE::level_set::LevelSetTransportForm transport_form{
      svmp::FE::level_set::LevelSetTransportForm::Advective};
  svmp::FE::level_set::LevelSetVelocityOptions velocity{};
  svmp::FE::level_set::LevelSetBoundPreservingOptions bound_preserving{};
  svmp::FE::level_set::LevelSetConservativePhaseOptions conservative_phase{};
  std::vector<OpenBoundary> open_boundaries{};
  svmp::FE::level_set::LevelSetReinitializationOptions reinitialization{};
  svmp::FE::level_set::LevelSetVolumeCorrectionOptions volume_correction{};
  std::optional<ActiveCutVolumeRequest> volume_cut_request{};
  bool static_capillary_equilibrium_enabled{false};
  svmp::FE::level_set::LevelSetStaticCapillaryEquilibriumOptions
      static_capillary_equilibrium{};
  bool static_capillary_equilibrium_initialized{false};
  bool curvature_projection_enabled{false};
  std::string curvature_field_name{};
  int curvature_projection_cadence_steps{1};
  svmp::FE::level_set::LevelSetCurvatureProjectionOptions curvature_projection{};
  bool volume_target_initialized{false};
  svmp::FE::Real volume_target{0.0};
  svmp::FE::Real volume_correction_reference_minimum_edge_length{0.0};
  svmp::FE::Real cumulative_volume_correction_interface_displacement{0.0};
  svmp::FE::Real cumulative_volume_correction_contact_line_displacement{0.0};
  bool conservative_phase_initialized{false};
  bool
      pointwise_impermeable_velocity_tolerance_explicitly_requested{
          false};
  std::optional<
      svmp::FE::level_set::LevelSetP1PhaseTransportGraph>
      conservative_phase_graph{};
};

bool hasExplicitUnsupportedConservativePhasePointwiseWallContract(
    std::span<const LevelSetMaintenanceRequest> requests) noexcept
{
  return std::any_of(
      requests.begin(), requests.end(), [](const auto& request) {
        return request.conservative_phase.enabled &&
               request
                   .pointwise_impermeable_velocity_tolerance_explicitly_requested;
      });
}

enum class LevelSetMaintenanceScheduleStage : std::uint64_t {
  SteadyInitialization = 1u,
  TransientInitialization = 2u,
  ProspectiveAcceptedEndpoint = 3u,
  AcceptedEndpointPostStep = 4u,
};

struct CanonicalLevelSetMaintenanceSchedule {
  std::vector<std::uint64_t> words{};
  bool supported{true};
};

struct CanonicalLevelSetMaintenanceGeometryState {
  std::vector<std::uint64_t> words{};
  bool supported{true};
};

void appendMaintenanceScheduleWord(
    std::vector<std::uint64_t>& words,
    std::uint64_t value)
{
  words.push_back(value);
}

void appendMaintenanceScheduleBool(
    std::vector<std::uint64_t>& words,
    bool value)
{
  appendMaintenanceScheduleWord(words, value ? 1u : 0u);
}

void appendMaintenanceScheduleSigned(
    std::vector<std::uint64_t>& words,
    std::int64_t value)
{
  appendMaintenanceScheduleWord(
      words, static_cast<std::uint64_t>(value));
}

template <typename Enum>
void appendMaintenanceScheduleEnum(
    std::vector<std::uint64_t>& words,
    Enum value)
{
  static_assert(std::is_enum_v<Enum>);
  using Underlying = std::underlying_type_t<Enum>;
  if constexpr (std::is_signed_v<Underlying>) {
    appendMaintenanceScheduleSigned(
        words, static_cast<std::int64_t>(value));
  } else {
    appendMaintenanceScheduleWord(
        words, static_cast<std::uint64_t>(value));
  }
}

void appendMaintenanceScheduleReal(
    std::vector<std::uint64_t>& words,
    double value)
{
  appendMaintenanceScheduleWord(
      words, std::bit_cast<std::uint64_t>(value));
}

void appendMaintenanceScheduleString(
    std::vector<std::uint64_t>& words,
    std::string_view value)
{
  appendMaintenanceScheduleWord(
      words, static_cast<std::uint64_t>(value.size()));
  for (const unsigned char byte : value) {
    appendMaintenanceScheduleWord(
        words, static_cast<std::uint64_t>(byte));
  }
}

void appendMaintenanceScheduleOptionalInt(
    std::vector<std::uint64_t>& words,
    const std::optional<int>& value)
{
  appendMaintenanceScheduleBool(words, value.has_value());
  appendMaintenanceScheduleSigned(
      words, static_cast<std::int64_t>(value.value_or(0)));
}

void appendMaintenanceScheduleOptionalReal(
    std::vector<std::uint64_t>& words,
    const std::optional<svmp::FE::Real>& value)
{
  appendMaintenanceScheduleBool(words, value.has_value());
  appendMaintenanceScheduleReal(
      words, static_cast<double>(value.value_or(0.0)));
}

void appendMaintenanceScheduleActiveCutRequest(
    std::vector<std::uint64_t>& words,
    const std::optional<ActiveCutVolumeRequest>& request)
{
  appendMaintenanceScheduleBool(words, request.has_value());
  if (!request.has_value()) {
    return;
  }
  appendMaintenanceScheduleString(
      words, request->level_set_field_name);
  appendMaintenanceScheduleString(words, request->domain_id);
  appendMaintenanceScheduleString(words, request->equation_type);
  appendMaintenanceScheduleEnum(words, request->origin);
  appendMaintenanceScheduleSigned(
      words, request->requested_interface_marker);
  appendMaintenanceScheduleReal(words, request->isovalue);
  appendMaintenanceScheduleOptionalInt(
      words, request->quadrature_order);
  appendMaintenanceScheduleOptionalInt(
      words, request->interface_quadrature_order);
  appendMaintenanceScheduleOptionalInt(
      words, request->volume_quadrature_order);
  appendMaintenanceScheduleEnum(words, request->geometry_mode);
  appendMaintenanceScheduleEnum(
      words, request->implicit_cut_backend);
  appendMaintenanceScheduleEnum(
      words, request->implicit_cut_fallback_policy);
  appendMaintenanceScheduleEnum(
      words, request->geometry_tangent_policy);
  appendMaintenanceScheduleBool(
      words, request->geometry_tangent_policy_explicit);
  appendMaintenanceScheduleReal(
      words, request->implicit_cut_root_tolerance);
  appendMaintenanceScheduleReal(
      words, request->implicit_cut_root_coordinate_tolerance);
  appendMaintenanceScheduleSigned(
      words, request->implicit_cut_root_max_iterations);
  appendMaintenanceScheduleSigned(
      words, request->implicit_cut_max_subdivision_depth);
  appendMaintenanceScheduleSigned(
      words, request->affected_cell_neighborhood_layers);
  appendMaintenanceScheduleEnum(words, request->active_side);
  appendMaintenanceScheduleEnum(words, request->volume_retention);
  appendMaintenanceScheduleBool(
      words, request->allow_corner_linearized_geometry);
  appendMaintenanceScheduleBool(
      words,
      request->require_production_qualified_implicit_cut_backend);
}

void appendMaintenanceScheduleGraphMetadata(
    std::vector<std::uint64_t>& words,
    const std::optional<
        svmp::FE::level_set::LevelSetP1PhaseTransportGraph>& graph)
{
  appendMaintenanceScheduleBool(words, graph.has_value());
  if (!graph.has_value()) {
    return;
  }
  appendMaintenanceScheduleBool(
      words, static_cast<bool>(graph->collective_state));
  appendMaintenanceScheduleBool(words, graph->success);
  appendMaintenanceScheduleBool(
      words, graph->partition_of_unity_satisfied);
  appendMaintenanceScheduleBool(
      words, graph->gradient_partition_satisfied);
  appendMaintenanceScheduleBool(
      words, graph->positive_control_volumes_satisfied);
  appendMaintenanceScheduleBool(
      words, graph->gradient_row_sum_satisfied);
  appendMaintenanceScheduleBool(
      words, graph->measure_closure_satisfied);
  appendMaintenanceScheduleBool(
      words, graph->edge_ownership_satisfied);
  appendMaintenanceScheduleBool(words, graph->distributed);
  appendMaintenanceScheduleBool(
      words, graph->replicated_sparse_graph);
  appendMaintenanceScheduleSigned(words, graph->dimension);
  appendMaintenanceScheduleSigned(words, graph->parallel_size);
  appendMaintenanceScheduleSigned(
      words, graph->maximum_quadrature_order);
  appendMaintenanceScheduleWord(
      words, static_cast<std::uint64_t>(graph->cells));
  appendMaintenanceScheduleWord(
      words, static_cast<std::uint64_t>(graph->nodes));
  appendMaintenanceScheduleWord(
      words,
      static_cast<std::uint64_t>(
          graph->lumped_control_volume.size()));
  appendMaintenanceScheduleWord(
      words,
      static_cast<std::uint64_t>(
          graph->diagonal_gradient.size()));
  appendMaintenanceScheduleWord(
      words,
      static_cast<std::uint64_t>(
          graph->boundary_column_sum.size()));
  appendMaintenanceScheduleWord(
      words, static_cast<std::uint64_t>(graph->edges.size()));
  // The graph caches rank-local mesh event counters so each partition can
  // decide when its own graph is stale.  Equally valid partitions can advance
  // those counters a different number of times, so they are not replicated
  // request semantics and must not participate in exact schedule consensus.
  // The graph's replicated shape, invariant flags, and FE DOF-layout identity
  // above/below remain part of the collective preflight.
  appendMaintenanceScheduleWord(words, graph->dof_layout_revision);
}

std::uint64_t levelSetMaintenanceRequestActionBits(
    const LevelSetMaintenanceRequest& request,
    int completed_step)
{
  const bool conservative_reinitialization_due =
      request.conservative_phase.enabled &&
      svmp::FE::level_set::shouldReinitializeLevelSet(
          request.reinitialization, completed_step);
  const bool accepted_reinitialization_due =
      !request.conservative_phase.enabled &&
      svmp::FE::level_set::shouldReinitializeLevelSet(
          request.reinitialization, completed_step);
  const bool accepted_volume_due =
      !request.conservative_phase.enabled &&
      svmp::FE::level_set::shouldApplyLevelSetVolumeCorrection(
          request.volume_correction, completed_step);
  const bool all_request_volume_due =
      svmp::FE::level_set::shouldApplyLevelSetVolumeCorrection(
          request.volume_correction, completed_step);
  const bool artifact_due =
      request.conservative_phase.enabled &&
      request.conservative_phase.write_flux_artifacts &&
      request.conservative_phase.flux_artifact_cadence_steps > 0 &&
      completed_step >= 0 &&
      static_cast<std::uint64_t>(completed_step) %
              static_cast<std::uint64_t>(
                  request.conservative_phase
                      .flux_artifact_cadence_steps) ==
          0u;
  const bool functional_due =
      request.conservative_phase.enabled ||
      request.bound_preserving.enabled ||
      accepted_reinitialization_due ||
      all_request_volume_due;
  std::uint64_t bits = 0u;
  bits |= request.conservative_phase.enabled ? (1ull << 0u) : 0u;
  bits |= request.bound_preserving.enabled ? (1ull << 1u) : 0u;
  bits |= conservative_reinitialization_due ? (1ull << 2u) : 0u;
  bits |=
      request.velocity.source ==
              svmp::FE::level_set::LevelSetVelocitySource::
                  ConstantVector
          ? (1ull << 3u)
          : (1ull << 4u);
  bits |= accepted_reinitialization_due ? (1ull << 5u) : 0u;
  bits |= accepted_volume_due ? (1ull << 6u) : 0u;
  bits |= all_request_volume_due ? (1ull << 7u) : 0u;
  bits |= functional_due ? (1ull << 8u) : 0u;
  bits |= artifact_due ? (1ull << 9u) : 0u;
  bits |= request.conservative_phase.reconcile_geometry
              ? (1ull << 10u)
              : 0u;
  bits |= request.static_capillary_equilibrium_enabled
              ? (1ull << 11u)
              : 0u;
  return bits;
}

CanonicalLevelSetMaintenanceSchedule
canonicalLevelSetMaintenanceRequestSchedule(
    const std::vector<LevelSetMaintenanceRequest>& requests,
    LevelSetMaintenanceScheduleStage stage,
    int completed_step)
{
  CanonicalLevelSetMaintenanceSchedule schedule;
  auto& words = schedule.words;
  words.reserve(32u + 224u * requests.size());
  appendMaintenanceScheduleWord(words, 3u);
  appendMaintenanceScheduleEnum(words, stage);
  appendMaintenanceScheduleSigned(words, completed_step);
  appendMaintenanceScheduleWord(
      words, static_cast<std::uint64_t>(requests.size()));
  std::uint64_t aggregate_action_bits = 0u;
  for (const auto& request : requests) {
    aggregate_action_bits |=
        levelSetMaintenanceRequestActionBits(
            request, completed_step);
  }
  appendMaintenanceScheduleWord(words, aggregate_action_bits);

  for (const auto& request : requests) {
    appendMaintenanceScheduleWord(
        words,
        levelSetMaintenanceRequestActionBits(
            request, completed_step));
    appendMaintenanceScheduleString(
        words, request.level_set_field_name);
    appendMaintenanceScheduleReal(words, request.isovalue);
    appendMaintenanceScheduleEnum(words, request.transport_form);

    appendMaintenanceScheduleString(
        words, request.velocity.field_name);
    appendMaintenanceScheduleEnum(words, request.velocity.source);
    appendMaintenanceScheduleBool(
        words, request.velocity.auto_register_field);
    appendMaintenanceScheduleBool(
        words, static_cast<bool>(request.velocity.space));
    schedule.supported =
        !request.velocity.space && schedule.supported;
    for (const auto value : request.velocity.constant_value) {
      appendMaintenanceScheduleReal(
          words, static_cast<double>(value));
    }
    appendMaintenanceScheduleString(
        words,
        request.velocity
            .algebraic_extension_source_field_name);

    appendMaintenanceScheduleBool(
        words, request.bound_preserving.enabled);
    appendMaintenanceScheduleReal(
        words, request.bound_preserving.bound_tolerance);
    appendMaintenanceScheduleReal(
        words, request.bound_preserving.sign_tolerance);
    appendMaintenanceScheduleReal(
        words, request.bound_preserving.maximum_courant);
    appendMaintenanceScheduleReal(
        words, request.bound_preserving.courant_tolerance);
    appendMaintenanceScheduleBool(
        words,
        request.bound_preserving.enforce_courant_limit);
    appendMaintenanceScheduleBool(
        words,
        request.bound_preserving
            .enforce_impermeable_boundaries);
    appendMaintenanceScheduleReal(
        words,
        request.bound_preserving
            .impermeable_normal_velocity_tolerance);

    appendMaintenanceScheduleBool(
        words, request.conservative_phase.enabled);
    appendMaintenanceScheduleString(
        words,
        request.conservative_phase.liquid_indicator.field_name);
    appendMaintenanceScheduleEnum(
        words,
        request.conservative_phase.liquid_indicator.source);
    appendMaintenanceScheduleBool(
        words,
        request.conservative_phase.liquid_indicator
            .auto_register_field);
    appendMaintenanceScheduleEnum(
        words, request.conservative_phase.liquid_side);
    appendMaintenanceScheduleReal(
        words, request.conservative_phase.invariant_tolerance);
    appendMaintenanceScheduleReal(
        words,
        request.conservative_phase.component_activity_tolerance);
    appendMaintenanceScheduleReal(
        words, request.conservative_phase.maximum_courant);
    appendMaintenanceScheduleBool(
        words,
        request.conservative_phase.enforce_courant_limit);
    appendMaintenanceScheduleBool(
        words,
        request.conservative_phase.require_constant_preservation);
    appendMaintenanceScheduleBool(
        words, request.conservative_phase.write_flux_artifacts);
    appendMaintenanceScheduleSigned(
        words,
        request.conservative_phase
            .flux_artifact_cadence_steps);
    appendMaintenanceScheduleBool(
        words,
        request.conservative_phase
            .classify_nonprimary_components_as_satellites);
    appendMaintenanceScheduleWord(
        words,
        static_cast<std::uint64_t>(
            request.conservative_phase.fixed_flux_regions.size()));
    for (const auto& region :
         request.conservative_phase.fixed_flux_regions) {
      appendMaintenanceScheduleString(words, region.name);
      appendMaintenanceScheduleEnum(words, region.kind);
      for (const auto value : region.minimum) {
        appendMaintenanceScheduleReal(words, value);
      }
      for (const auto value : region.maximum) {
        appendMaintenanceScheduleReal(words, value);
      }
    }
    appendMaintenanceScheduleReal(
        words,
        request.conservative_phase
            .impermeable_normal_velocity_tolerance);
    appendMaintenanceScheduleBool(
        words,
        request
            .pointwise_impermeable_velocity_tolerance_explicitly_requested);
    appendMaintenanceScheduleBool(
        words, request.conservative_phase.reconcile_geometry);
    appendMaintenanceScheduleReal(
        words,
        request.conservative_phase.geometry_measure_tolerance);
    appendMaintenanceScheduleSigned(
        words,
        request.conservative_phase
            .geometry_correction_max_iterations);
    appendMaintenanceScheduleReal(
        words,
        request.conservative_phase
            .maximum_geometry_displacement_fraction);

    appendMaintenanceScheduleWord(
        words,
        static_cast<std::uint64_t>(
            request.open_boundaries.size()));
    for (const auto& boundary : request.open_boundaries) {
      appendMaintenanceScheduleString(
          words, boundary.face_name);
      appendMaintenanceScheduleBool(words, boundary.inflow);
      appendMaintenanceScheduleOptionalReal(
          words, boundary.literal_inflow_value);
    }

    appendMaintenanceScheduleBool(
        words, request.reinitialization.enabled);
    appendMaintenanceScheduleEnum(
        words, request.reinitialization.method);
    appendMaintenanceScheduleSigned(
        words, request.reinitialization.cadence_steps);
    appendMaintenanceScheduleSigned(
        words, request.reinitialization.max_iterations);
    appendMaintenanceScheduleReal(
        words,
        request.reinitialization.pseudo_time_step_scale);
    appendMaintenanceScheduleReal(
        words, request.reinitialization.interface_band_width);
    appendMaintenanceScheduleReal(
        words,
        request.reinitialization.signed_distance_tolerance);
    appendMaintenanceScheduleReal(
        words, request.reinitialization.preserve_band_width);
    appendMaintenanceScheduleReal(
        words,
        request.reinitialization.max_zero_set_displacement);

    appendMaintenanceScheduleBool(
        words, request.volume_correction.enabled);
    appendMaintenanceScheduleSigned(
        words, request.volume_correction.cadence_steps);
    appendMaintenanceScheduleBool(
        words,
        request.volume_correction
            .use_initial_negative_volume_as_target);
    appendMaintenanceScheduleReal(
        words,
        request.volume_correction.target_negative_volume);
    appendMaintenanceScheduleReal(
        words, request.volume_correction.volume_tolerance);
    appendMaintenanceScheduleSigned(
        words, request.volume_correction.max_iterations);
    appendMaintenanceScheduleReal(
        words,
        request.volume_correction.minimum_relative_volume_error);
    appendMaintenanceScheduleReal(
        words,
        request.volume_correction
            .maximum_interface_displacement_fraction);
    appendMaintenanceScheduleReal(
        words,
        request.volume_correction
            .maximum_cumulative_interface_displacement_fraction);
    appendMaintenanceScheduleActiveCutRequest(
        words, request.volume_cut_request);

    appendMaintenanceScheduleBool(
        words, request.static_capillary_equilibrium_enabled);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium.target_liquid_volume);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium.volume_tolerance);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .projected_gradient_tolerance);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .pressure_representability_max_residual_norm);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .pressure_representability_max_relative_distance);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .physical_equilibrium_max_residual_norm);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .constant_pressure_kkt_max_residual_norm);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .constant_pressure_kkt_max_relative_distance);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .finite_difference_reference_coefficient_scale);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .finite_difference_relative_step);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .minimum_finite_difference_step);
    appendMaintenanceScheduleSigned(
        words,
        request.static_capillary_equilibrium
            .finite_difference_max_shrinks);
    appendMaintenanceScheduleSigned(
        words,
        request.static_capillary_equilibrium.max_iterations);
    appendMaintenanceScheduleSigned(
        words,
        request.static_capillary_equilibrium
            .max_line_search_iterations);
    appendMaintenanceScheduleSigned(
        words,
        request.static_capillary_equilibrium
            .max_topology_epoch_transitions);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .projected_gradient_inverse_stiffness);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium.tangent_trust_radius);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .maximum_coefficient_update_linf);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium.line_search_shrink);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium.armijo_fraction);
    appendMaintenanceScheduleSigned(
        words,
        request.static_capillary_equilibrium
            .limited_memory_history_size);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .limited_memory_curvature_tolerance);
    appendMaintenanceScheduleReal(
        words,
        request.static_capillary_equilibrium
            .minimum_volume_merit_penalty);
    appendMaintenanceScheduleBool(
        words, request.static_capillary_equilibrium_initialized);

    appendMaintenanceScheduleBool(
        words, request.curvature_projection_enabled);
    appendMaintenanceScheduleString(
        words, request.curvature_field_name);
    appendMaintenanceScheduleSigned(
        words, request.curvature_projection_cadence_steps);
    appendMaintenanceScheduleReal(
        words, request.curvature_projection.isovalue);
    appendMaintenanceScheduleReal(
        words,
        request.curvature_projection.gradient_tolerance);
    appendMaintenanceScheduleReal(
        words,
        request.curvature_projection.normal_equation_tolerance);
    appendMaintenanceScheduleReal(
        words,
        request.curvature_projection
            .max_normalized_fit_residual);
    appendMaintenanceScheduleSigned(
        words,
        request.curvature_projection.max_neighbor_rings);
    appendMaintenanceScheduleSigned(
        words,
        request.curvature_projection
            .max_neighbor_fallback_vertices);
    appendMaintenanceScheduleSigned(
        words,
        request.curvature_projection
            .max_zero_fallback_vertices);
    appendMaintenanceScheduleReal(
        words,
        request.curvature_projection
            .supplemental_sample_weight);
    appendMaintenanceScheduleEnum(
        words, request.curvature_projection.recovery_mode);
    appendMaintenanceScheduleReal(
        words,
        request.curvature_projection
            .kinematic_area_gradient_filter_coefficient);
    appendMaintenanceScheduleBool(
        words,
        request.curvature_projection
            .kinematic_area_gradient_negative_liquid_side);
    appendMaintenanceScheduleSigned(
        words,
        static_cast<std::int64_t>(
            request.curvature_projection
                .kinematic_area_gradient_young_walls.size()));
    for (const auto& wall :
         request.curvature_projection
             .kinematic_area_gradient_young_walls) {
      appendMaintenanceScheduleSigned(words, wall.boundary_marker);
      appendMaintenanceScheduleReal(
          words, wall.equilibrium_contact_angle_radians);
    }
    appendMaintenanceScheduleReal(
        words,
        request.curvature_projection.narrow_band_width);
    appendMaintenanceScheduleSigned(
        words,
        request.curvature_projection.smoothing_iterations);
    appendMaintenanceScheduleReal(
        words,
        request.curvature_projection.smoothing_relaxation);
    appendMaintenanceScheduleEnum(
        words, request.curvature_projection.smoothing_mode);

    appendMaintenanceScheduleBool(
        words, request.volume_target_initialized);
    appendMaintenanceScheduleReal(words, request.volume_target);
    appendMaintenanceScheduleReal(
        words,
        request.volume_correction_reference_minimum_edge_length);
    appendMaintenanceScheduleReal(
        words,
        request
            .cumulative_volume_correction_interface_displacement);
    appendMaintenanceScheduleReal(
        words,
        request
            .cumulative_volume_correction_contact_line_displacement);
    appendMaintenanceScheduleBool(
        words, request.conservative_phase_initialized);
    appendMaintenanceScheduleGraphMetadata(
        words, request.conservative_phase_graph);
  }
  return schedule;
}

void appendCanonicalLevelSetMaintenanceScheduleSection(
    std::vector<std::uint64_t>& words,
    const CanonicalLevelSetMaintenanceSchedule& schedule)
{
  // A distinct section tag and length make the enclosing commit-state
  // serialization unambiguous even when the request schema grows.
  appendMaintenanceScheduleWord(
      words, 0x4c534d5343484544ull);
  appendMaintenanceScheduleBool(words, schedule.supported);
  appendMaintenanceScheduleWord(
      words,
      static_cast<std::uint64_t>(schedule.words.size()));
  words.insert(
      words.end(),
      schedule.words.begin(),
      schedule.words.end());
}

void appendCanonicalFreeSurfaceGeometryRevision(
    std::vector<std::uint64_t>& words,
    const svmp::FE::interfaces::FreeSurfaceGeometryRevision& revision)
{
  appendMaintenanceScheduleString(words, revision.source_id);
  appendMaintenanceScheduleString(words, revision.domain_id);
  appendMaintenanceScheduleSigned(words, revision.interface_marker);
  appendMaintenanceScheduleReal(words, revision.isovalue);
  appendMaintenanceScheduleWord(
      words, revision.source_layout_revision);
  appendMaintenanceScheduleWord(
      words, revision.source_value_revision);
  appendMaintenanceScheduleWord(
      words, revision.mesh_geometry_revision);
  appendMaintenanceScheduleWord(
      words, revision.mesh_topology_revision);
  appendMaintenanceScheduleWord(
      words, revision.ownership_revision);
  appendMaintenanceScheduleWord(
      words, revision.numbering_revision);
  appendMaintenanceScheduleWord(
      words, revision.quadrature_policy_key);
  appendMaintenanceScheduleWord(
      words, revision.snapshot_revision_key);
}

CanonicalLevelSetMaintenanceGeometryState
canonicalLevelSetMaintenanceGeometryState(
    const application::core::SimulationComponents& sim,
    const std::vector<LevelSetMaintenanceRequest>& requests)
{
  CanonicalLevelSetMaintenanceGeometryState state;
  auto& words = state.words;
  appendMaintenanceScheduleWord(words, 1u);
  appendMaintenanceScheduleBool(
      words, static_cast<bool>(sim.fe_system));
  if (!sim.fe_system) {
    state.supported = false;
    return state;
  }

  const auto operator_revision =
      sim.fe_system->operatorRevisionSnapshot();
  appendMaintenanceScheduleBool(words, operator_revision.valid);
  // Raw operator mesh event counters are partition-local: equally valid
  // partitions can process different numbers of local geometry, topology,
  // ownership, or numbering events.  The full authoritative snapshot
  // revisions serialized below carry the communicator-replicated mesh
  // geometry/topology/ownership/numbering identities instead.
  appendMaintenanceScheduleWord(
      words, operator_revision.fe_layout.space);
  appendMaintenanceScheduleWord(
      words, operator_revision.fe_layout.dof_layout);
  appendMaintenanceScheduleWord(
      words, operator_revision.fe_layout.constraint_layout);
  appendMaintenanceScheduleWord(
      words, operator_revision.fe_layout.block_layout);
  appendMaintenanceScheduleWord(
      words, operator_revision.system_layout_key);
  appendMaintenanceScheduleEnum(
      words, operator_revision.geometry_state);
  appendMaintenanceScheduleEnum(
      words, operator_revision.geometry_use);

  const auto* context =
      sim.fe_system->cutIntegrationContext();
  appendMaintenanceScheduleBool(words, context != nullptr);
  appendMaintenanceScheduleWord(
      words, static_cast<std::uint64_t>(requests.size()));
  for (const auto& request : requests) {
    appendMaintenanceScheduleBool(
        words, request.volume_cut_request.has_value());
    if (!request.volume_cut_request.has_value()) {
      continue;
    }

    const auto marker =
        resolvedActiveCutVolumeInterfaceMarker(
            *sim.fe_system, *request.volume_cut_request);
    appendMaintenanceScheduleBool(words, marker.has_value());
    appendMaintenanceScheduleSigned(
        words, marker.value_or(-1));
    if (!marker.has_value() || context == nullptr) {
      state.supported = false;
      appendMaintenanceScheduleBool(words, false);
      appendMaintenanceScheduleBool(words, false);
      appendMaintenanceScheduleBool(words, false);
      continue;
    }

    const bool has_snapshot_binding =
        context->hasFreeSurfaceGeometrySnapshotForMarker(*marker);
    appendMaintenanceScheduleBool(
        words, has_snapshot_binding);
    const auto bound_snapshot_revision =
        has_snapshot_binding
            ? context->freeSurfaceGeometrySnapshotRevisionForMarker(
                  *marker)
            : 0u;
    appendMaintenanceScheduleWord(
        words, bound_snapshot_revision);

    const bool has_expected_source_revision =
        context->hasExpectedGeneratedSourceValueRevision(*marker);
    appendMaintenanceScheduleBool(
        words, has_expected_source_revision);
    appendMaintenanceScheduleWord(
        words,
        has_expected_source_revision
            ? context->expectedGeneratedSourceValueRevision(*marker)
            : 0u);

    const auto& snapshots =
        context->freeSurfaceGeometrySnapshots();
    const auto found = std::find_if(
        snapshots.begin(), snapshots.end(),
        [&](const auto& snapshot) {
          return snapshot &&
                 snapshot->revision().interface_marker == *marker &&
                 snapshot->revision().snapshot_revision_key ==
                     bound_snapshot_revision;
        });
    const bool has_bound_snapshot =
        has_snapshot_binding && found != snapshots.end();
    appendMaintenanceScheduleBool(
        words, has_bound_snapshot);
    if (has_bound_snapshot) {
      appendCanonicalFreeSurfaceGeometryRevision(
          words, (*found)->revision());
    } else {
      state.supported = false;
    }
  }

  using GeometrySnapshot =
      svmp::FE::interfaces::FreeSurfaceGeometrySnapshot;
  std::vector<const GeometrySnapshot*> ordered_snapshots;
  if (context != nullptr) {
    const auto& snapshots =
        context->freeSurfaceGeometrySnapshots();
    ordered_snapshots.reserve(snapshots.size());
    for (const auto& snapshot : snapshots) {
      ordered_snapshots.push_back(snapshot.get());
    }
    std::sort(
        ordered_snapshots.begin(), ordered_snapshots.end(),
        [](const GeometrySnapshot* left,
           const GeometrySnapshot* right) {
          if (left == nullptr || right == nullptr) {
            return left == nullptr && right != nullptr;
          }
          const auto& lhs = left->revision();
          const auto& rhs = right->revision();
          return std::tuple{
                     lhs.interface_marker,
                     lhs.source_id,
                     lhs.domain_id,
                     std::bit_cast<std::uint64_t>(
                         static_cast<double>(lhs.isovalue)),
                     lhs.source_layout_revision,
                     lhs.source_value_revision,
                     lhs.snapshot_revision_key} <
                 std::tuple{
                     rhs.interface_marker,
                     rhs.source_id,
                     rhs.domain_id,
                     std::bit_cast<std::uint64_t>(
                         static_cast<double>(rhs.isovalue)),
                     rhs.source_layout_revision,
                     rhs.source_value_revision,
                     rhs.snapshot_revision_key};
        });
  }
  appendMaintenanceScheduleWord(
      words,
      static_cast<std::uint64_t>(
          ordered_snapshots.size()));
  for (const auto* snapshot : ordered_snapshots) {
    appendMaintenanceScheduleBool(
        words, snapshot != nullptr);
    if (snapshot == nullptr) {
      state.supported = false;
      continue;
    }
    appendCanonicalFreeSurfaceGeometryRevision(
        words, snapshot->revision());
  }
  return state;
}

void appendCanonicalLevelSetMaintenanceGeometrySection(
    std::vector<std::uint64_t>& words,
    const CanonicalLevelSetMaintenanceGeometryState& geometry)
{
  appendMaintenanceScheduleWord(
      words, 0x4c534d47454f4d31ull);
  appendMaintenanceScheduleBool(words, geometry.supported);
  appendMaintenanceScheduleWord(
      words,
      static_cast<std::uint64_t>(geometry.words.size()));
  words.insert(
      words.end(),
      geometry.words.begin(),
      geometry.words.end());
}

void requireCollectiveLevelSetMaintenanceRequestSchedule(
    const std::vector<LevelSetMaintenanceRequest>& requests,
    LevelSetMaintenanceScheduleStage stage,
    int completed_step,
    const svmp::MeshComm& comm)
{
  const auto schedule =
      canonicalLevelSetMaintenanceRequestSchedule(
          requests, stage, completed_step);
  const bool identical =
      application::core::
          collectiveLevelSetMaintenanceCanonicalWordsAgree(
              schedule.words, comm);
  if (!identical) {
    throw std::runtime_error(
        "[svMultiPhysics::Application] Ordered level-set maintenance "
        "request schedule differs across the FE communicator.");
  }
  if (!schedule.supported) {
    throw std::runtime_error(
        "[svMultiPhysics::Application] Maintenance request schedule "
        "preflight does not support an embedded velocity FunctionSpace; "
        "production requests must resolve velocity fields through the FE "
        "system.");
  }
}

